"""Three additional roof traditions with representative geographic points."""
JEJU='https://ijto.or.kr/english/?cid=22'
SAMOA='https://whc.unesco.org/document/168061#page=249'
CHICKEE='https://floridaseminoletourism.com/seminole-spaces-chickees/'
cases=[
 ('jeju','Seongeup, Jeju','South Korea',33.387,126.800,'Low thatched roof secured with rope netting','Grass thatch; rope; stone and earth walls',None,'Jeju Tourism Organization describes rope-secured thatch as an adaptation to rain and wind.','Jeju courtyard households and communal roof maintenance.','documented regional building tradition',JEJU,'https://www.visitjeju.net/en/themtour/view?contentsid=CNTS_200000000010595&menuId=DOM_000002100000000221'),
 ('samoa','Apia area, Upolu','Samoa',-13.833,-171.767,'Open-sided fale; contemporary metal-roof example','Timber posts; metal roof in photograph; traditional examples use thatch',None,'UNESCO educational account describes open-sided fale ventilation and woven blinds for wind and rain.','Fale accommodate family life, meetings and ceremonies; the photograph shows a contemporary metal-roof variation.','documented Samoan tradition; representative area',SAMOA,'https://www.samoa.travel/samoa-travel-blog/your-guide-to-samoan-fales/'),
 ('chickee','Hollywood Reservation, Florida','United States',26.051,-80.209,'Open-sided chickee with palm-thatched roof','Palm thatch; cypress frame',None,'Seminole tourism describes palm-thatch rain protection and open-sided shelter suited to South Florida.','Seminole building tradition; the selected historic photograph shows the reservation in 1960.','documented Seminole tradition; historic photograph',CHICKEE,'https://www.safezone.fsu.edu/seminole-tribe/know.html')]

def narratives(story):
 return {
 'jeju':[story('jeju-ropes',list(range(1,13)),'precipitation','Thatch held down against wind and rain','Jeju Tourism Organization describes a tight checkerboard of ropes holding down the thatch. The roof and stone-and-earth walls were developed in response to the island’s windy, rainy environment.','rope netting over the low thatch roof',[JEJU,'https://english1.visitkorea.or.kr/e_book/access/ecatalogt.jsp?Dir=913&callmode=normal&catimage=&eclang=ko&start=114&um=s'],'documented Jeju tradition','The feature works year-round. Monthly precipitation and mean wind do not measure gust resistance or establish a storm-safe design.')],
 'samoa':[story('fale-air',list(range(1,13)),'temperature','A shelter open to the breeze','The UNESCO account describes the open sides beneath a traditional fale roof as allowing ventilation in a hot climate. Woven palm-leaf blinds can shelter occupants from wind and rain.','open perimeter beneath the roof',[SAMOA,'https://www.samoa.travel/samoa-travel-blog/your-guide-to-samoan-fales/'],'documented Samoan tradition','The photographed fale has a contemporary metal roof. The explanation concerns its open-sided form, not the thermal properties of metal. Apia is a representative regional climate point.')],
 'chickee':[story('chickee-rain',list(range(1,13)),'precipitation','Palm thatch as a rain shelter','Seminole tourism describes cabbage-palm thatch as protecting occupants from rainfall. Open sides distinguish the chickee from an enclosed house.','palm-thatched roof and open sides',[CHICKEE,'https://www.safezone.fsu.edu/seminole-tribe/know.html'],'Seminole tradition; not a performance test','The photograph dates to 1960. The 1991–2020 chart provides recent regional climate context, not the weather when the photograph was taken.'),story('chickee-breeze',[5,6,7,8,9,10],'temperature','Open sides for summer heat','Florida Seminole Tourism explains how the open sides of chickees let occupants keep cool during South Florida summers. The roof provides shelter while leaving the perimeter open.','open perimeter below the palm thatch',[CHICKEE],'documented Seminole explanation','No indoor cooling value is claimed. Climate, available materials and the history of displacement all inform this building tradition.')]
 }
